import { useQuery } from '@tanstack/react-query';
import type { BinInfo } from '@z-ui/shared';

/**
 * Public BIN lookup from static files generated by `npm run bin:sync`
 * (apps/web/public/bin/<first 3 digits>.json). Only the first three digits ever leave
 * the browser (as the file name) and nothing reaches the API — on Cloudflare these are
 * free static-asset requests.
 */

export interface BinMeta {
  count: number;
  files: number;
  generatedAt: string;
  /** Most recent "last confirmed" date among the records. */
  newest?: string | null;
  source: string;
  license: string;
  attribution: string;
}

type Shard = Record<string, string[]>;

const shards = new Map<string, Promise<Shard | null>>();

function loadShard(prefix: string): Promise<Shard | null> {
  let p = shards.get(prefix);
  if (!p) {
    p = fetch(`/bin/${prefix}.json`)
      .then(async (r) => {
        // The SPA fallback answers unknown paths with index.html — treat non-JSON as "no file".
        if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) return null;
        return (await r.json()) as Shard;
      })
      .catch(() => {
        shards.delete(prefix);
        return null;
      });
    shards.set(prefix, p);
  }
  return p;
}

const toInfo = (bin: string, r: string[]): BinInfo => {
  const [scheme, type, level, issuer, country, countryName, phone, url, seen] = r;
  const info: BinInfo = { bin, source: 'library' };
  if (scheme) info.scheme = scheme;
  if (type) info.type = type;
  if (level) info.level = level;
  if (issuer) info.issuer = issuer;
  if (country) info.country = country;
  if (countryName) info.countryName = countryName;
  if (phone) info.phone = phone;
  if (url) info.url = url;
  if (seen) info.seen = seen;
  return info;
};

/**
 * What to show for a card's BIN: a hand correction saved on the card wins; otherwise the current
 * public list (fresher than the copy saved when the card was entered); otherwise that copy.
 */
export function effectiveBinInfo(saved: BinInfo | null | undefined, library: BinInfo | null | undefined, bin: string | null | undefined): BinInfo | null {
  if (saved?.source === 'manual' && saved.bin === bin) return saved;
  return library ?? (saved && saved.bin === bin ? saved : null);
}

/** Exact 6-digit lookup (null if unknown or the BIN files are not installed). */
export async function lookupBin(bin: string): Promise<BinInfo | null> {
  if (!/^\d{6}$/.test(bin)) return null;
  const shard = await loadShard(bin.slice(0, 3));
  const r = shard?.[bin];
  return r ? toInfo(bin, r) : null;
}

/** All BINs starting with a 3–6 digit prefix (first `limit` matches, ascending). */
export async function searchBins(prefix: string, limit = 100): Promise<{ total: number; items: BinInfo[] } | null> {
  if (!/^\d{3,6}$/.test(prefix)) return null;
  const shard = await loadShard(prefix.slice(0, 3));
  if (!shard) return null;
  const keys = Object.keys(shard)
    .filter((k) => k.startsWith(prefix))
    .sort();
  return { total: keys.length, items: keys.slice(0, limit).map((k) => toInfo(k, shard[k]!)) };
}

export const useBinMeta = () =>
  useQuery({
    queryKey: ['bin-meta'],
    queryFn: async (): Promise<BinMeta | null> => {
      const r = await fetch('/bin/meta.json');
      if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) return null;
      return (await r.json()) as BinMeta;
    },
    staleTime: Infinity,
    retry: false,
  });

export const useBinLookup = (bin: string | null | undefined) =>
  useQuery({
    queryKey: ['bin', bin ?? ''],
    queryFn: () => lookupBin(bin!),
    enabled: !!bin && /^\d{6}$/.test(bin),
    staleTime: Infinity,
  });

/** "US" → 🇺🇸 */
export const flagOf = (alpha2?: string) =>
  alpha2 && /^[A-Z]{2}$/.test(alpha2) ? String.fromCodePoint(...[...alpha2].map((c) => 0x1f1e6 + c.charCodeAt(0) - 65)) : '';
